from fastapi import FastAPI
from fastapi.openapi.utils import get_openapi


def use_problem_details(app: FastAPI) -> None:
    """Make the generated spec say what Roombook really sends for errors:
    application/problem+json with the Problem schema, never FastAPI's default 422 body."""

    def openapi() -> dict:
        if app.openapi_schema:
            return app.openapi_schema
        spec = get_openapi(title=app.title, version=app.version, servers=app.servers, routes=app.routes)
        for operation in (op for path in spec["paths"].values() for op in path.values()):
            for status, response in operation["responses"].items():
                if status.startswith(("4", "5")):
                    response["content"] = {"application/problem+json": {"schema": {"$ref": "#/components/schemas/Problem"}}}
        schemas = spec["components"]["schemas"]
        schemas.pop("HTTPValidationError", None)
        schemas.pop("ValidationError", None)
        app.openapi_schema = spec
        return spec

    app.openapi = openapi
